competitive-landscape.code:
ALTERNATIVES = {
    "incumbent-suite": {"speed": 2, "setup": 1, "compliance": 4},
    "spreadsheet":     {"speed": 3, "setup": 4, "compliance": 1},
    "do-nothing":      {"speed": 1, "setup": 5, "compliance": 0},
}
SEGMENTS = {
    "seed-ops-team":   {"speed": 0.3, "setup": 0.5, "compliance": 0.2},
    "midsize-parttime-admin": {"speed": 0.4, "setup": 0.2, "compliance": 0.4},
}
HIREABLE = {
    "seed-ops-team": ["incumbent-suite", "spreadsheet", "do-nothing"],
    "midsize-parttime-admin": ["incumbent-suite", "spreadsheet"],
}


def best_coverage(alternatives, weights):
    best_name, best_score = None, -1.0
    for name in sorted(alternatives):
        sc = sum(alternatives[name][axis] * w for axis, w in weights.items())
        if sc > best_score:
            best_name, best_score = name, sc
    return (best_name, best_score)


scores = {}
for seg in sorted(SEGMENTS):
    hire = {a: ALTERNATIVES[a] for a in HIREABLE[seg]}
    name, sc = best_coverage(hire, SEGMENTS[seg])
    scores[seg] = (name, sc)
    print(f"{seg}: best alternative = {name} at {sc:.2f}/5")
wedge = min(sorted(scores), key=lambda s: scores[s][1])
print(f"wedge: {wedge} - best option only scores {scores[wedge][1]:.2f}/5")
print("next: kill test = 10 discovery calls, >=6 must name the pain unprompted")

experiment-design.code:
ARMS = {
    "control": (52, 200),
    "variant": (68, 200),
}
MIN_N = 200
DECISION_BAR = 32.0


def evaluate_experiment(arms):
    return {name: a / t * 100 for name, (a, t) in arms.items()}


for name in sorted(ARMS):
    a, t = ARMS[name]
    if t < MIN_N:
        print(f"sample gate FAILED: {name} has {t} < {MIN_N} - no read allowed")
        raise SystemExit
rates = evaluate_experiment(ARMS)
for name in sorted(rates):
    a, t = ARMS[name]
    print(f"{name}: {a}/{t} = {rates[name]:.1f}%")
lift = rates["variant"] - rates["control"]
print(f"lift: {lift:+.1f}pp")
verdict = "BUILD" if rates["variant"] >= DECISION_BAR else "KILL"
print(f"pre-registered bar {DECISION_BAR:.1f}%: {verdict}")

